class Solution { fun watchedVideosByFriends(watchedVideos:List<List<String>>,friends:Array<IntArray>,id:Int,levelValue:Int):List<String>{val queue=java.util.ArrayDeque<Int>();val seen=BooleanArray(friends.size);queue.addLast(id);seen[id]=true;var level=levelValue;while(level-->0){var size=queue.size;while(size-->0){val person=queue.removeFirst();for(next in friends[person])if(!seen[next]){seen[next]=true;queue.addLast(next)}}};val frequency=mutableMapOf<String,Int>();while(queue.isNotEmpty())for(video in watchedVideos[queue.removeFirst()])frequency[video]=(frequency[video]?:0)+1;return frequency.keys.sortedWith(compareBy<String>{frequency[it]}.thenBy{it})} }
